(* [comment removed for export] *)
Ltac exp2f_row_step MI :=
  let kk := fresh "kk" in
  lazymatch goal with |- context [Z.land (bv_unsigned ?X) 31] => set (kk := Z.land (bv_unsigned X) 31) in * end;
  let KR := fresh "KR" in
  assert (KR : 0 <= kk < 32) by (unfold kk; change 31 with (Z.ones 5); rewrite Z.land_ones by lia; apply Z.mod_pos_bound; lia);
  clearbody kk;
  replace (188264 + kk * 8) with (kk * 8 + 188264) by (clear; lia);
  let rowbs := fresh "rowbs" in let RBL := fresh "RBL" in let ROW := fresh "ROW" in
  destruct (exp2f_row _ kk MI KR) as (rowbs & RBL & ROW).

Section EXPF.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.

